import React, { useState } from "react";

function App() {
  const [isLogin, setIsLogin] = useState(false);

  const [signupData, setSignupData] = useState({
    firstName: "",
    surname: "",
    day: "",
    month: "",
    year: "",
    gender: "",
    emailOrMobile: "",
    password: "",
  });

  const [loginData, setLoginData] = useState({
    emailOrMobile: "",
    password: "",
  });

  const days = Array.from({ length: 31 }, (_, i) => i + 1);
  const months = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
  ];
  const years = Array.from({ length: 100 }, (_, i) => new Date().getFullYear() - i);

  const handleSignupChange = (e) => {
    setSignupData({
      ...signupData,
      [e.target.name]: e.target.value,
    });
  };

  const handleLoginChange = (e) => {
    setLoginData({
      ...loginData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSignupSubmit = async (e) => {
    e.preventDefault();

    const payload = {
      firstName: signupData.firstName,
      surname: signupData.surname,
      day: signupData.day,
      month: signupData.month,
      year: signupData.year,
      gender: signupData.gender,
      emailOrMobile: signupData.emailOrMobile,
      password: signupData.password,
    };

    try {
      const response = await fetch("http://localhost:8081/api/v1/auth/register", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });

      const data = await response.text();

      if (response.ok) {
        alert("Successfully registered an account!");
        console.log(data);

        setSignupData({
          firstName: "",
          surname: "",
          day: "",
          month: "",
          year: "",
          gender: "",
          emailOrMobile: "",
          password: "",
        });

        setIsLogin(true);
      } else {
        alert(data || "Registration failed.");
      }
    } catch (error) {
      console.error("Signup error:", error);
      alert("Could not connect to backend.");
    }
  };

  const handleLoginSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await fetch("http://localhost:8081/api/v1/auth/login", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(loginData),
      });

      const data = await response.text();

      if (response.ok) {
        alert("Login successful!");
        console.log(data);
      } else {
        alert(data || "Login failed.");
      }
    } catch (error) {
      console.error("Login error:", error);
      alert("Could not connect to backend.");
    }
  };

  return (
    <div className="page-wrapper">
      <div className="auth-card">
        {!isLogin ? (
          <>
            <div className="auth-left">
              <h1 className="auth-title">SIGN UP</h1>
              <p className="auth-subtitle">Get started on RentMate</p>

              <form onSubmit={handleSignupSubmit}>
                <div className="name-row">
                  <div className="form-group">
                    <label>First Name</label>
                    <input
                      type="text"
                      name="firstName"
                      placeholder="First name"
                      value={signupData.firstName}
                      onChange={handleSignupChange}
                      required
                    />
                  </div>

                  <div className="form-group">
                    <label>Surname</label>
                    <input
                      type="text"
                      name="surname"
                      placeholder="Surname"
                      value={signupData.surname}
                      onChange={handleSignupChange}
                      required
                    />
                  </div>
                </div>

                <div className="form-group">
                  <label>Date of Birth</label>
                  <div className="dob-row">
                    <select name="day" value={signupData.day} onChange={handleSignupChange} required>
                      <option value="">Day</option>
                      {days.map((day) => (
                        <option key={day} value={day}>
                          {day}
                        </option>
                      ))}
                    </select>

                    <select name="month" value={signupData.month} onChange={handleSignupChange} required>
                      <option value="">Month</option>
                      {months.map((month) => (
                        <option key={month} value={month}>
                          {month}
                        </option>
                      ))}
                    </select>

                    <select name="year" value={signupData.year} onChange={handleSignupChange} required>
                      <option value="">Year</option>
                      {years.map((year) => (
                        <option key={year} value={year}>
                          {year}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>

                <div className="form-group">
                  <label>Gender</label>
                  <select
                    name="gender"
                    value={signupData.gender}
                    onChange={handleSignupChange}
                    required
                  >
                    <option value="">Select your gender</option>
                    <option value="Male">Male</option>
                    <option value="Female">Female</option>
                    <option value="Prefer not to say">Prefer not to say</option>
                  </select>
                </div>

                <div className="form-group">
                  <label>Email or Mobile Number</label>
                  <input
                    type="text"
                    name="emailOrMobile"
                    placeholder="Enter Mobile Number or Email Address"
                    value={signupData.emailOrMobile}
                    onChange={handleSignupChange}
                    required
                  />
                </div>

                <div className="form-group">
                  <label>Password</label>
                  <input
                    type="password"
                    name="password"
                    placeholder="Enter Password"
                    value={signupData.password}
                    onChange={handleSignupChange}
                    required
                  />
                </div>

                <button type="submit" className="primary-btn">
                  CREATE ACCOUNT
                </button>
              </form>
            </div>

            <div className="auth-right">
              <h2 className="brand-title">RentMate</h2>
              <p className="brand-text">
                Already have an account? Sign in and continue exploring rentals.
              </p>
              <button className="secondary-btn" onClick={() => setIsLogin(true)}>
                SIGN IN
              </button>
            </div>
          </>
        ) : (
          <>
            <div className="auth-right">
              <h2 className="brand-title">RentMate</h2>
              <p className="brand-text">
                Don’t have an account yet? Sign up now and enjoy our site.
              </p>
              <button className="secondary-btn" onClick={() => setIsLogin(false)}>
                SIGN UP
              </button>
            </div>

            <div className="auth-left">
              <h1 className="auth-title">SIGN IN</h1>
              <p className="auth-subtitle">Sign in with Email & Password</p>

              <form onSubmit={handleLoginSubmit}>
                <div className="form-group">
                  <label>Mobile Number or Email Address</label>
                  <input
                    type="text"
                    name="emailOrMobile"
                    placeholder="Enter Mobile Number or Email Address"
                    value={loginData.emailOrMobile}
                    onChange={handleLoginChange}
                    required
                  />
                </div>

                <div className="form-group">
                  <label>Password</label>
                  <input
                    type="password"
                    name="password"
                    placeholder="Password"
                    value={loginData.password}
                    onChange={handleLoginChange}
                    required
                  />
                </div>

                <button type="submit" className="primary-btn">
                  SIGN IN
                </button>
              </form>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

export default App;
